head.b:skin:
/* ==========================================================================
   MEIWATV - USER-FRIENDLY LIVE SPORTS PORTAL (PRO EDITION)
   ========================================================================== */
:root {
  --bg-dark: #070a10;
  --bg-card: #0e1422;
  --bg-card-hover: #151e33;
  --bg-surface: #121929;
  --bg-header: #05080e;

  --primary-green: #10b981;
  --primary-neon: #00eb1f;
  --primary-glow: rgba(16, 185, 129, 0.35);

  --accent-gold: #ffe400;
  --accent-red: #ef4444;
  --accent-red-glow: rgba(239, 68, 68, 0.4);
  --accent-blue: #3b82f6;

  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-dim: #64748b;

  --border-subtle: rgba(255, 255, 255, 0.08);
  --border-hover: rgba(16, 185, 129, 0.5);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --font-main: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-heading: 'Outfit', sans-serif;
  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-dark);
  color: var(--text-main);
  font-family: var(--font-main);
  font-size: 14px;
  line-height: 1.5;
  min-height: 100vh;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
  transition: var(--transition);
}

/* TOP NAVBAR */
.site-header {
  background: var(--bg-header);
  border-bottom: 1px solid var(--border-subtle);
  position: sticky;
  top: 0;
  z-index: 1000;
  backdrop-filter: blur(12px);
}

.nav-container {
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 20px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.brand-logo {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: linear-gradient(135deg, #101726, #1c2840);
  padding: 6px 14px;
  border-radius: 12px;
  border: 1px solid var(--border-subtle);
  text-decoration: none;
  flex-shrink: 0;
}
.brand-logo:hover {
  border-color: var(--primary-green);
  box-shadow: 0 4px 20px var(--primary-glow);
}
.brand-logo-img {
  height: 36px;
  width: auto;
  object-fit: contain;
}

/* Navigation Links - Mulai dengan LIVE, tanpa Beranda */
.nav-menu-links {
  display: flex;
  align-items: center;
  gap: 6px;
  list-style: none;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.nav-menu-links::-webkit-scrollbar {
  display: none;
}

.nav-item-btn {
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-muted);
  font-size: 13.5px;
  font-weight: 700;
  padding: 8px 14px;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}
.nav-item-btn:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.06);
}
.nav-item-btn.active {
  color: #000 !important;
  background: var(--primary-green) !important;
  font-weight: 800;
  box-shadow: 0 2px 10px var(--primary-glow);
}
.nav-item-btn.btn-nav-live.active {
  color: #fff !important;
  background: var(--accent-red) !important;
  box-shadow: 0 2px 12px var(--accent-red-glow);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}
.btn-saweria-top {
  background: linear-gradient(135deg, #ffbe0b, #fb5607);
  color: #000 !important;
  font-weight: 800;
  font-size: 12.5px;
  padding: 7px 14px;
  border-radius: var(--radius-full);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  box-shadow: 0 2px 10px rgba(251, 86, 7, 0.3);
}
.btn-saweria-top:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 15px rgba(251, 86, 7, 0.5);
}
.btn-apk-top {
  background: var(--bg-surface);
  color: var(--primary-green) !important;
  border: 1px solid var(--primary-green);
  font-weight: 700;
  font-size: 12.5px;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.btn-apk-top:hover {
  background: var(--primary-green);
  color: #000 !important;
}

/* ADSTERRA SPONSOR BANNER */
.adsterra-banner-container {
  max-width: 1440px;
  margin: 12px auto 0 auto;
  padding: 0 20px;
}
.adsterra-wrapper-box {
  background: var(--bg-surface);
  border: 1px dashed rgba(16, 185, 129, 0.3);
  border-radius: var(--radius-md);
  padding: 8px 16px;
  text-align: center;
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* MAIN WORKSPACE */
.main-full-container {
  max-width: 1440px;
  margin: 14px auto 40px auto;
  padding: 0 20px;
}

/* 2-COLUMN THEATER LAYOUT: PLAYER (LEFT) + QUICK LIVE PLAYLIST (RIGHT) */
.theater-grid-layout {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 18px;
  margin-bottom: 24px;
}
@media (max-width: 1080px) {
  .theater-grid-layout {
    grid-template-columns: 1fr;
  }
}

/* LEFT: THEATER PLAYER CARD */
.theater-player-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
}

.player-top-bar {
  background: #090e18;
  padding: 10px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-subtle);
  flex-wrap: wrap;
  gap: 10px;
}
.player-match-badge {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
}
.live-indicator {
  background: rgba(239, 68, 68, 0.15);
  color: var(--accent-red);
  border: 1px solid rgba(239, 68, 68, 0.3);
  padding: 2px 10px;
  border-radius: var(--radius-full);
  font-size: 11.5px;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.player-server-group {
  display: flex;
  align-items: center;
  gap: 6px;
}
.btn-server {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 700;
  padding: 5px 12px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.btn-server:hover {
  color: #fff;
  border-color: rgba(255, 255, 255, 0.3);
}
.btn-server.active {
  background: var(--primary-green);
  color: #000;
  border-color: var(--primary-green);
  font-weight: 800;
}

/* 16:9 VIDEO FRAME */
.video-container-169 {
  position: relative;
  width: 100%;
  padding-top: 56.25%;
  background: #000;
  overflow: hidden;
}
.video-container-169 video,
.video-container-169 iframe {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border: none;
  outline: none;
  background: #000;
}

.player-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(circle at center, rgba(14, 20, 34, 0.75) 0%, rgba(5, 8, 14, 0.95) 100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 20px;
  text-align: center;
  z-index: 10;
}
.player-overlay-league {
  color: var(--primary-green);
  font-weight: 800;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 6px;
}
.player-overlay-title {
  font-family: var(--font-heading);
  font-size: 22px;
  font-weight: 800;
  color: #fff;
  margin-bottom: 6px;
  max-width: 90%;
}
.player-overlay-time {
  color: var(--text-muted);
  font-size: 13px;
  margin-bottom: 18px;
}
.btn-overlay-play {
  background: linear-gradient(135deg, var(--primary-green), #059669);
  color: #000;
  font-size: 14px;
  font-weight: 800;
  padding: 11px 26px;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  box-shadow: 0 4px 20px var(--primary-glow);
  transition: var(--transition);
}
.btn-overlay-play:hover {
  transform: scale(1.05);
  background: var(--primary-neon);
}

/* PLAYER BOTTOM INFO BAR */
.player-match-detail-bar {
  background: #090e18;
  padding: 12px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid var(--border-subtle);
  gap: 12px;
  flex-wrap: wrap;
}
.detail-match-teams {
  display: flex;
  align-items: center;
  gap: 12px;
  font-weight: 700;
  font-size: 14px;
}
.detail-team-logo {
  width: 28px;
  height: 28px;
  object-fit: contain;
}
.detail-score-pill {
  background: #000;
  color: var(--accent-gold);
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 14px;
  padding: 3px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 228, 0, 0.3);
}
.btn-open-source {
  background: rgba(16, 185, 129, 0.15);
  border: 1px solid var(--primary-green);
  color: var(--primary-green);
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
}
.btn-open-source:hover {
  background: var(--primary-green);
  color: #000;
}

/* RIGHT: QUICK LIVE & POPULAR MATCH PLAYLIST */
.quick-playlist-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  max-height: 520px;
}
.quick-playlist-header {
  background: #090e18;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.quick-playlist-title {
  font-size: 13.5px;
  font-weight: 800;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 8px;
}
.quick-playlist-count {
  background: var(--accent-red);
  color: #fff;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  font-size: 11px;
  font-weight: 800;
}
.quick-playlist-body {
  padding: 10px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}
.quick-match-row {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 10px 12px;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.quick-match-row:hover, .quick-match-row.active {
  background: var(--bg-card-hover);
  border-color: var(--primary-green);
  transform: translateX(2px);
}
.quick-match-row-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  color: var(--text-muted);
}
.quick-match-row-league {
  color: var(--primary-green);
  font-weight: 700;
  max-width: 65%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.quick-match-row-teams {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-weight: 700;
  font-size: 13px;
  color: #fff;
}
.quick-match-row-score {
  background: #000;
  color: var(--accent-gold);
  font-size: 12px;
  font-weight: 800;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
}

/* SECTION DIVIDERS & CONTROLS */
.schedule-filter-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 20px;
  flex-wrap: wrap;
  background: var(--bg-card);
  padding: 14px 18px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-subtle);
}
.sports-chips-nav {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.sport-chip {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
  font-size: 12.5px;
  font-weight: 700;
  padding: 7px 14px;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.sport-chip:hover {
  color: #fff;
  border-color: rgba(255, 255, 255, 0.25);
}
.sport-chip.active {
  color: #000 !important;
  background: var(--primary-green) !important;
  border-color: var(--primary-green) !important;
  font-weight: 800;
  box-shadow: 0 2px 10px var(--primary-glow);
}
.sport-chip.chip-live.active {
  color: #fff !important;
  background: var(--accent-red) !important;
  border-color: var(--accent-red) !important;
  box-shadow: 0 2px 10px var(--accent-red-glow);
}
.chip-count {
  background: rgba(0, 0, 0, 0.35);
  padding: 1px 7px;
  border-radius: var(--radius-full);
  font-size: 10px;
  font-weight: 800;
}

.search-box-wrap {
  position: relative;
  min-width: 240px;
}
.search-input {
  width: 100%;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  color: #fff;
  font-size: 13px;
  padding: 8px 14px 8px 36px;
  border-radius: var(--radius-full);
  outline: none;
  transition: var(--transition);
}
.search-input:focus {
  border-color: var(--primary-green);
  box-shadow: 0 0 10px var(--primary-glow);
}
.search-icon {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-dim);
  font-size: 13px;
}

/* SPORT CATEGORY SECTION HEADERS / PEMISAH OLAHRAGA */
.sport-category-group-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 28px 0 14px 0;
  padding-bottom: 8px;
  border-bottom: 2px solid rgba(255, 255, 255, 0.08);
}
.sport-category-title {
  font-family: var(--font-heading);
  font-size: 18px;
  font-weight: 800;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 10px;
}
.sport-category-badge {
  background: rgba(16, 185, 129, 0.15);
  color: var(--primary-green);
  border: 1px solid rgba(16, 185, 129, 0.3);
  padding: 2px 10px;
  border-radius: var(--radius-full);
  font-size: 12px;
  font-weight: 800;
}

/* FULL-WIDTH MATCH CARDS GRID */
.match-cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(400px, 1fr));
  gap: 16px;
}
@media (max-width: 600px) {
  .match-cards-grid {
    grid-template-columns: 1fr;
  }
}

.match-card-item {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  cursor: pointer;
  transition: var(--transition);
}
.match-card-item:hover, .match-card-item.active {
  background: var(--bg-card-hover);
  border-color: var(--primary-green);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.4);
}

.match-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
  color: var(--text-muted);
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  padding-bottom: 8px;
}
.match-league-title {
  font-weight: 700;
  color: var(--primary-green);
  display: flex;
  align-items: center;
  gap: 6px;
  max-width: 65%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.match-time-tag {
  font-size: 11.5px;
  color: var(--text-muted);
}

.match-card-body {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.team-side {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
  font-weight: 700;
  font-size: 13.5px;
  color: #fff;
}
.team-side.away {
  justify-content: flex-end;
  text-align: right;
}
.card-team-logo {
  width: 32px;
  height: 32px;
  object-fit: contain;
  flex-shrink: 0;
}

.match-center-score {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  min-width: 70px;
}
.score-badge-live {
  background: #000;
  color: var(--accent-gold);
  border: 1px solid rgba(255, 228, 0, 0.4);
  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 800;
  padding: 2px 10px;
  border-radius: var(--radius-sm);
}
.score-badge-upcoming {
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-muted);
  border: 1px solid var(--border-subtle);
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 800;
  padding: 2px 10px;
  border-radius: var(--radius-sm);
}
.live-dot-tag {
  color: var(--accent-red);
  font-size: 10.5px;
  font-weight: 800;
  display: flex;
  align-items: center;
  gap: 4px;
}

.match-card-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}
.stream-btn-chip {
  flex: 1;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
  font-size: 11.5px;
  font-weight: 700;
  padding: 6px 8px;
  border-radius: var(--radius-sm);
  text-align: center;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  transition: var(--transition);
}
.stream-btn-chip:hover {
  background: var(--primary-green);
  color: #000;
  border-color: var(--primary-green);
}

/* HIDE UNWANTED BLOGGER STUFF */
.post-hidden-meta,
.event-link-preview,
.match-source-link {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
}

body.script:
//
// POPUNDER ADSTERRA MONETIZATION let lastAdsterraTime = 0; function triggerAdsterra() { const now = Date.now(); if (now - lastAdsterraTime > 45000) { lastAdsterraTime = now; try { const adUrl = "https://www.profitableratecpmnetwork.com/r1x7jbv2ys?key=c06365de807e3e8605b4e7e665953775"; window.open(adUrl, "_blank", "noopener,noreferrer"); } catch (e) {} } }
