if (isDirectFlv && typeof flvjs !== 'undefined' && flvjs.isSupported()) { if (iframe) iframe.style.display = 'none'; if (video) { video.style.display = 'block'; try { flvPlayerInstance = flvjs.createPlayer({ type: 'flv', url: streamUrl, isLive: true, cors: true }); flvPlayerInstance.attachMediaElement(video); flvPlayerInstance.load(); video.play().catch(() => {}); return; } catch (e) { console.warn('FLV fallback:', e); } } }
if (isDirectM3u8 && typeof Hls !== 'undefined' && Hls.isSupported()) { if (iframe) iframe.style.display = 'none'; if (video) { video.style.display = 'block'; try { hlsInstance = new Hls({ enableWorker: true, lowLatencyMode: true }); hlsInstance.loadSource(streamUrl); hlsInstance.attachMedia(video); hlsInstance.on(Hls.Events.MANIFEST_PARSED, function() { video.play().catch(() => {}); }); return; } catch (e) { console.warn('HLS fallback:', e); } } }
// Embed via Clean Web Source URL (Eliminates domainkqt refused to connect) if (video) { video.pause(); video.style.display = 'none'; } if (iframe) { iframe.style.display = 'block'; const finalEmbedUrl = (isAjaxEndpoint || !streamUrl) ? cleanWebUrl : streamUrl; iframe.src = finalEmbedUrl; } }
function openCurrentMatchNewTab() { triggerAdsterra(); if (currentActiveMatch) { const url = currentActiveMatch.streamJalur3 || currentActiveMatch.postUrl || currentActiveMatch.streamJalur1 || window.location.href; window.open(url, '_blank', 'noopener,noreferrer'); } }
function shareCurrentMatch() { if (navigator.share && currentActiveMatch) { navigator.share({ title: currentActiveMatch.title + ' - Live Streaming MeiwaSports', url: window.location.href }).catch(() => {}); } else { navigator.clipboard.writeText(window.location.href); alert('Link siaran pertandingan berhasil disalin!'); } }
// 10. REAL-TIME MATCHES SYNC function fetchLiveMatchesDirect() { const syncSources = [ 'https://raw.githubusercontent.com/adityafarid0112/meiwatv/main/matches.json', 'https://cdn.jsdelivr.net/gh/adityafarid0112/meiwatv@main/matches.json' ];
function tryFetchSource(idx) { if (idx >= syncSources.length) return; fetch(syncSources[idx] + '?_t=' + Date.now()) .then(res => { if (!res.ok) throw new Error('Sync source failed'); return res.json(); }) .then(data => { if (Array.isArray(data) && data.length > 0) { allLoadedMatches = data; renderMatchList(allLoadedMatches); } }) .catch(() => { tryFetchSource(idx + 1); }); }
tryFetchSource(0); }
